const cantidad = Number(texto);
if (texto.trim() === "" || !Number.isInteger(cantidad) || cantidad < 0 || cantidad > 6) { console.log("Reserva inválida"); }
else if (cantidad === 0) { console.log("Disponible"); }
else if (cantidad === 6) { console.log("Lleno"); }
else { console.log("Ocupado"); }
